class Solution {
public:
    int minArraySum(vector<int>& nums,int k,int op1,int op2) {
        const int INF=1000000000;
        vector<vector<int>> dp(op1+1,vector<int>(op2+1,INF));
        dp[0][0]=0;
        for (int x:nums) {
            vector<vector<int>> next(op1+1,vector<int>(op2+1,INF));
            for (int a=0;a<=op1;++a) for (int b=0;b<=op2;++b) {
                if (dp[a][b]==INF) continue;
                next[a][b]=min(next[a][b],dp[a][b]+x);
                int half=(x+1)/2;
                if (a<op1) next[a+1][b]=min(next[a+1][b],dp[a][b]+half);
                if (b<op2 && x>=k) next[a][b+1]=min(next[a][b+1],dp[a][b]+x-k);
                if (a<op1 && b<op2) {
                    if (half>=k) next[a+1][b+1]=min(next[a+1][b+1],dp[a][b]+half-k);
                    if (x>=k) next[a+1][b+1]=min(next[a+1][b+1],dp[a][b]+(x-k+1)/2);
                }
            }
            dp.swap(next);
        }
        int ans=INF;
        for (auto& row:dp) for (int v:row) ans=min(ans,v);
        return ans;
    }
};
